    imageGrad: "linear-gradient(to bottom right, #3b82f6, #1d4ed8)",
    content: `
      <h3>Конец бумажной эпохи</h3>
      <p>С 2020 года все новые и ввезенные в Россию автомобили получают только Электронные паспорта транспортного средства (ЭПТС). Это цифровая запись в базе данных. Выдают лишь бумажную выписку, которая не имеет юридической силы.</p>
      <h3>Проблема: ГИБДД vs СЭП</h3>
      <p>Многие водители по старинке подписывают бумажный договор купли-продажи (ДКП), отдают деньги, едут в ГИБДД и ставят машину на учет. Они думают, что стали полноправными владельцами. <strong>Но в ЭПТС владельцем по-прежнему числится продавец!</strong></p>
      <p>ГИБДД не вносит изменения в базу ЭПТС, они только выдают свидетельство о регистрации (СТС). Если вы не заставите продавца сменить собственника в электронном ПТС, в будущем вы столкнетесь с проблемами при перепродаже авто, получении страховки или оформлении кредита под залог.</p>
      <h3>Как правильно менять собственника:</h3>
      <p>Сделка должна сопровождаться действиями на портале <strong>Системы электронных паспортов (СЭП)</strong> (elpts.ru). Продавец заходит туда через Госуслуги, находит свою машину и нажимает «Сменить собственника», указав ваш СНИЛС. Вы заходите в свой кабинет и нажимаете «Подтвердить». Только после этого машина полностью ваша!</p>
      <div class="mt-8 p-6 bg-gray-50 border border-gray-100 rounded-2xl shadow-sm">
        <h4 class="text-xl font-bold text-gray-900 mb-2">💳 Как безопасно перевести деньги за авто?</h4>
        <p class="text-gray-600 mb-5">Не возите с собой пакеты наличных. Откройте премиальную дебетовую карту с высокими лимитами на переводы, чтобы рассчитаться с продавцом мгновенно и безопасно.</p>
        <a href="/#debit-cards" class="inline-block bg-gray-900 hover:bg-indigo-600 text-white font-bold py-3 px-8 rounded-xl transition-colors duration-300">Выбрать дебетовую карту &rarr;</a>
      </div>
    `
