    imageGrad: "linear-gradient(to bottom right, #0ea5e9, #0369a1)",
    content: `
      <h3>Заморозка прав</h3>
      <p>Вас останавливает инспектор ДПС для проверки документов, пробивает права по базе и заявляет: <em>«Ваше удостоверение приостановлено судебными приставами, машину на штрафстоянку»</em>. Если вы сядете за руль с таким ограничением, суд может лишить вас прав на год или отправить на обязательные работы.</p>
      <h3>За какие долги могут ограничить права?</h3>
      <p>Пристав имеет право вынести такое постановление, если сумма вашего долга превышает <strong>10 000 рублей</strong>, и это долг по:</p>
      <ul class="list-disc pl-5 mb-4 space-y-2 text-gray-700">
        <li>Алиментам.</li>
        <li>Возмещению вреда здоровью или ущерба от преступления.</li>
        <li>Неоплаченным штрафам ГИБДД.</li>
      </ul>
      <p><em>Важно:</em> За обычные банковские кредиты, микрозаймы или долги по ЖКХ пристав <strong>НЕ имеет права</strong> лишать вас прав напрямую! (Это возможно только через отдельное решение суда).</p>
      <h3>Кого лишать запрещено законом:</h3>
      <p>Даже если у вас миллионный долг по алиментам, пристав не тронет права, если:</p>
      <ol class="list-decimal pl-5 mb-4 space-y-2 text-gray-700">
        <li>Автомобиль — ваш единственный <strong>законный</strong> источник дохода (вы официально работаете водителем, таксистом с лицензией, курьером).</li>
        <li>Вы живете в труднодоступной местности, куда не ходит общественный транспорт.</li>
        <li>Вы инвалид 1-2 группы или на вашем иждивении находится ребенок-инвалид.</li>
      </ol>
      <div class="mt-8 p-6 bg-gray-50 border border-gray-100 rounded-2xl shadow-sm">
        <h4 class="text-xl font-bold text-gray-900 mb-2">⚖️ Боитесь потерять права из-за долгов?</h4>
        <p class="text-gray-600 mb-5">Если платить по счетам нечем, запустите процедуру банкротства. С момента признания вас банкротом все ограничения ФССП (на выезд, аресты карт и водительские права) снимаются.</p>
        <a href="/#bankruptcy" class="inline-block bg-gray-900 hover:bg-indigo-600 text-white font-bold py-3 px-8 rounded-xl transition-colors duration-300">Узнать о списании долгов &rarr;</a>
      </div>
    `
