    date: "10 августа 2026",
    imageGrad: "linear-gradient(to bottom right, #3b82f6, #1d4ed8)",
    content: `
      <h3>Разница, ломающая судьбы</h3>
      <p>Многие путают эти два документа, хотя их юридическая суть противоположна. Главное правило: <strong>Дарственная (договор дарения) действует при жизни, а Завещание — только после смерти.</strong></p>
      <h3>Дарственная: Риск для дарителя</h3>
      <p>Как только вы подписываете договор дарения и относите его в Росреестр, квартира перестает быть вашей. Вы теряете на нее все права в ту же секунду. Вы подарили квартиру любимому внуку, а он через месяц женился, набрал долгов, и квартиру забрали приставы. Или внук просто попросил вас съехать. Оспорить или отменить дарственную практически невозможно.</p>
      <h3>Завещание: Риск для наследника</h3>
      <p>Вы написали завещание на дочь. Квартира остается вашей до конца ваших дней, вы можете продать ее или переписать завещание на соседа хоть сто раз. Для владельца это 100% безопасность. Но для наследника (дочери) это риск. После смерти могут объявиться "обязательные наследники" (пенсионеры, инвалиды), которые откусят часть квартиры вопреки вашей воле в завещании.</p>
      <p><strong>Золотая середина:</strong> Договор ренты (пожизненного содержания с иждивением). Квартира переходит наследнику, но с железным обременением — он не может ее продать и обязан вас содержать до конца жизни.</p>
      <div class="mt-8 p-6 bg-gray-50 border border-gray-100 rounded-2xl shadow-sm">
        <h4 class="text-xl font-bold text-gray-900 mb-2">🏠 Планируете выкупить долю у родственников?</h4>
        <p class="text-gray-600 mb-5">Если квартира досталась нескольким наследникам, лучше выкупить их доли и стать единоличным владельцем. Сравните ставки по ипотеке на вторичное жилье и доли.</p>
        <a href="/#mortgage" class="inline-block bg-gray-900 hover:bg-indigo-600 text-white font-bold py-3 px-8 rounded-xl transition-colors duration-300">Подобрать ипотеку &rarr;</a>
      </div>
    `
