    imageGrad: "linear-gradient(to bottom right, #dc2626, #991b1b)",
    content: `
      <h3>Офлайн-фишинг выходит на новый уровень</h3>
      <p>Мошенникам больше не нужно вам звонить. Они просто печатают тысячи фальшивых квитанций за услуги ЖКХ (свет, воду или мифическую «замену счетчиков») и раскидывают их по почтовым ящикам. Бумага выглядит идеально: ваш точный адрес, штрих-коды, печати и синие штампы.</p>
      <h3>В чем кроется ловушка?</h3>
      <p>В квитанции напечатан крупный <strong>QR-код для быстрой оплаты</strong>. Вы наводите на него камеру смартфона, и тут происходит одно из двух:</p>
      <ul class="list-disc pl-5 mb-4 space-y-2 text-gray-700">
        <li><strong>Подмена реквизитов.</strong> QR-код открывает ваше банковское приложение, но в поле «Получатель» указано не «Мосэнергосбыт», а счет физлица или подставного ИП (дроппера). Вы переводите 3-5 тысяч рублей прямо в карман мошеннику.</li>
        <li><strong>Загрузка вируса.</strong> QR-код ведет на фишинговый сайт, который под видом скачивания "новой квитанции" устанавливает на ваш Android-смартфон троянскую программу. Она перехватывает СМС от банка и сносит баланс под ноль.</li>
      </ul>
      <h3>Как защитить себя и пожилых родителей:</h3>
      <p>Никогда не платите по бумажным квитанциям! Зайдите в официальное приложение своего банка -> раздел «Платежи» -> «ЖКХ». Введите свой номер Лицевого Счета (ЕЛС). Банк сам покажет, есть ли у вас реальная задолженность в государственной базе ГИС ЖКХ. Если долга нет — рвите бумажку.</p>
      <div class="mt-8 p-6 bg-gray-50 border border-gray-100 rounded-2xl shadow-sm">
        <h4 class="text-xl font-bold text-gray-900 mb-2">💡 Платите за ЖКХ с выгодой и безопасно</h4>
        <p class="text-gray-600 mb-5">Оплачивая коммуналку через официальные приложения банков, вы не только защищены от мошенников, но и получаете кэшбэк. Сравните карты с возвратом за ЖКХ.</p>
        <a href="/#debit-cards" class="inline-block bg-gray-900 hover:bg-indigo-600 text-white font-bold py-3 px-8 rounded-xl transition-colors duration-300">Подобрать карту &rarr;</a>
      </div>
    `
