    title: "Мошенники украли деньги: в каких случаях по закону 2026 года банк ОБЯЗАН вернуть вам всё",
    excerpt: "Новая практика Верховного Суда и закон ЦБ: если вы перевели деньги злоумышленникам, ответственность может лечь на ваш банк. Как это работает.",
