    title: "Страхование вкладов АСВ: как вернуть 10 миллионов, если банк обанкротился",
    excerpt: "Все знают про лимит в 1.4 млн рублей. Но что делать, если вы продали квартиру, положили деньги в банк, а у него отозвали лицензию? Секреты страховки.",
