    date: "10 августа 2026",
    imageGrad: "linear-gradient(to bottom right, #f59e0b, #c2410c)",
    content: `
      <h3>Стандартный лимит АСВ</h3>
      <p>Агентство по страхованию вкладов (АСВ) гарантирует возврат ваших денег при отзыве лицензии у банка, но только в пределах <strong>1 400 000 рублей</strong> (с учетом набежавших процентов). Если у вас лежало 2 миллиона, остаток в 600 тысяч вы будете выбивать годами через суды в порядке очереди кредиторов.</p>
      <h3>Особые случаи: Лимит 10 000 000 рублей!</h3>
      <p>Мало кто знает, но по закону государство застрахует ваши деньги на сумму до 10 млн рублей, если эти средства попали на счет в результате <strong>особых жизненных ситуаций (и пролежали там не более 3 месяцев)</strong>:</p>
      <ul class="list-disc pl-5 mb-4 space-y-2 text-gray-700">
        <li>Продажа жилья (квартиры, дома, участка).</li>
        <li>Получение наследства (если деньги перевели вам на счет).</li>
        <li>Получение страховых выплат или компенсаций по суду (например, за ДТП).</li>
        <li>Деньги на счетах эскроу (если вы покупали новостройку у застройщика).</li>
      </ul>
      <h3>Как получить повышенную страховку?</h3>
      <p>При наступлении страхового случая (когда <a href="/article/114" class="text-blue-600 hover:underline">ЦБ отзывает у банка лицензию</a>), вам нужно подать в АСВ специальное заявление и приложить подтверждающие документы: договор купли-продажи квартиры или свидетельство о праве на наследство. Деньги вернут на счет в другом, здоровом банке.</p>
      <div class="mt-8 p-6 bg-gray-50 border border-gray-100 rounded-2xl shadow-sm">
        <h4 class="text-xl font-bold text-gray-900 mb-2">📈 Держите деньги в разных корзинах</h4>
        <p class="text-gray-600 mb-5">Самая надежная стратегия — дробить капитал и класть по 1.4 млн в разные крупные банки из списка системно значимых. Сравните лучшие ставки.</p>
        <a href="/#deposits" class="inline-block bg-gray-900 hover:bg-indigo-600 text-white font-bold py-3 px-8 rounded-xl transition-colors duration-300">Подобрать надежный банк &rarr;</a>
      </div>
    `
