    title: "Заградительные тарифы 115-ФЗ: как банки легально грабят бизнес при закрытии счета",
    excerpt: "Вам заблокировали счет по подозрению в обнале и просят заплатить 20% комиссии за вывод собственных денег? Как отбить свои миллионы.",
